def min_moves_to_opposite_parity(n, a):
    # Union-Find structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    # Group numbers by their parity
    parity_groups = {0: [], 1: []}
    for i in range(n):
        parity_groups[a[i] % 2].append(i)

    # Union all nodes with the same parity
    for group in parity_groups.values():
        for i in range(1, len(group)):
            union(group[0], group[i])

    # Find the nearest node of the opposite parity for each node
    result = [-1] * n
    visited = set()
    queue = deque()

    for i in range(n):
        if i not in visited:
            queue.append((i, 0))
            while queue:
                current, dist = queue.popleft()
                visited.add(current)
                if a[current] % 2 == 1 - a[i] % 2:
                    result[i] = dist
                    break
                for neighbor in [current - a[current], current + a[current]]:
                    if 0 <= neighbor < n and neighbor not in visited:
                        queue.append((neighbor, dist + 1))

    return result

